    \begin{algorithm}[H]
    \caption{Parallel Prefix Scan (\citet{Hillis1986DataPA}'s variation)}\label{alg:prefix_scan}
    \begin{algorithmic}
    \Require Associative Operator $\oplus$ and $\{x_i\}_{i=1}^{N}$
    \Ensure $\{z_k = \bigoplus_{i=1}^{k} x_i\}_{k=1}^{N}$
    \State $z \leftarrow x$
    \For{$i \leftarrow 1, \ldots, \floor{\log(N)}$}
        \For{$j \leftarrow 0, \ldots, N-1$} \textbf{in parallel}
            \If {$j < 2^i$}
                \State $z'_j \leftarrow z_j$
            \Else
                \State $z'_j \leftarrow z_j \oplus z_{j - 2^i}$
            \EndIf
        \EndFor
        \State $z \leftarrow z'$
    \EndFor
    \end{algorithmic}
    \end{algorithm}
\end{minipage}
